# Hypothesis: draw FULL diagonal lines (both dirs) through every seed, stopping at seeds and edges. Fill=union.
def sim(I,stop_seeds=True):
    n,m=I.shape
    seeds=set((r,c) for r in range(n) for c in range(m) if I[r][c]==mark if False else [x[0] for x in [(r,c)] if True])
